mapper.select:
SELECT T1.DECLARE_UUID AS declareUuid, T1.STATUS AS statusValid, T1.PROD_NAME AS prodName, T1.PROD_INS_ID AS prodInsId, T1.PROD_BRAND AS prodBrand, T1.PRD_SPEC_PROPERTY AS prdSpecProperty, T1.PROD_STAGE AS prodStage, T1.ISSUE_PARTY_ID AS issuePartyId, T1.APPROVER_NAME AS approverName, T1.APPROVER_ID AS approverId, T1.DESIGNER_NAME AS designerName, T1.DESIGNER_ID AS designerId, T1.MANAGER_NAME AS managerName, T1.MANAGER_ID AS managerId, T1.LIAISON_NAME AS liaisonName, T1.LIAISON_TEL AS liaisonTel, T1.LIAISON_MOBILE AS liaisonMobile, T1.LIAISON_EMAIL AS liaisonEmail, T1.RAISE_TYPE AS raiseType, T1.PROFIT_TYPE AS profitType, T1.IS_FHXGCP AS isFhxgcp, T1.TERMTYPE AS termtype, T1.EXC_FIN_SECTOR AS excFinSector, T1.INVEST_ARAE AS investArae, T1.INVEST_COUNTRY AS investCountry, T1.FINAN_SER_MODEL AS finanSerModel, T1.OPERATE_MODE AS operateMode, T1.IS_SHORT_TERM AS isShortTerm, T1.SHORT_TERM AS shortTerm, T1.IS_FREE_REDEM AS isFreeRedem, T1.CASH_MANA_CATE AS cashManaCate, T1.CMMODE AS cmmode , T1.PMMODE AS pmmode, T1.MNAME AS mname , T1.PRICED_MODE AS pricedMode, T1.IVSTORIENTATION AS ivstorientation, T1.CONT_MODE AS contMode, T1.COOPERATION_NAME AS cooperationName, T1.SALE_AREA AS saleArea, T1.RAISE_CCY AS raiseCcy, T1.CASH_PRIN_CCY AS cashPrinCcy, T1.CASH_PROF_CCY AS cashProfCcy, T1.SALE_AMT_STR AS saleAmtStr, T1.RAISE_AMT_PLAN AS raiseAmtPlan, T1.RAISE_PSTRDATE AS raisePstrdate, T1.RAISE_PENDDATE AS raisePenddate, T1.INVEST_PRIN_DATE AS investPrinDate, T1.INVEST_PROF_DATE AS investProfDate, T1.SALE_FEE_RATE AS saleFeeRate, T1.INVEST_FEE_RATE AS investFeeRate, T1.IN_DEP_NAME AS inDepName, T1.IN_DEP_CODE AS inDepCode, T1.OUT_DEP_CTRY AS outDepCtry, T1.OUT_DEP_NAME AS outDepName, T1.TRU_FEE_RATE AS truFeeRate, T1.RISK_LEVEL AS riskLevel, T1.RISK_TYPE AS riskType, T1.TERM_RIGHT_FLAG AS termRightFlag, T1.CUS_REDEEM_FLAG AS cusRedeemFlag, T1.CREDIT_FLAG AS creditFlag, T1.CREDIT_TYPE AS creditType, T1.CREDIT_MODE AS creditMode, T1.INV_TYPE_RAT AS invTypeRat, T1.YIELD AS yield, T1.REMARK AS remark, DATE_FORMAT(T1.UPDATE_TIME,'%Y-%m-%d') AS updateTime, T1.UPDATE_USER AS updateUser, T1.ERR_MSG AS errMsg, T1.FILE_NO AS fileNo, T1.FILE_NUM AS fileNum, T1.TEN_FILE AS tenFile, null AS orgData FROM CHB_PRD_DECLARE_INFO T1
1=1
AND T1.PROD_NAME LIKE concat(concat('%',#{prodName,jdbcType=VARCHAR}),'%')
AND T1.TERMTYPE = #{termtype}
ANd T1.OPERATE_MODE = #{operateMode}
AND T1.STATUS = #{status}
and T1.RAISE_PSTRDATE >= STR_TO_DATE(#{raisePstrdateStart},'%Y-%m-%d')
and T1.RAISE_PSTRDATE <= STR_TO_DATE(#{raisePstrdateEnd},'%Y-%m-%d')
union all SELECT T1.DATAUUID AS declareUuid, T1.STATUS AS statusValid, T1.PROD_NAME AS prodName, T1.PROD_INS_ID AS prodInsId, null AS prodBrand, null AS prdSpecProperty, null AS prodStage, null AS issuePartyId, null AS approverName, null AS approverId, null AS designerName, null AS designerId, null AS managerName, null AS managerId, null AS liaisonName, null AS liaisonTel, null AS liaisonMobile, null AS liaisonEmail, null AS raiseType, null AS profitType, null AS isFhxgcp, T1.TERMTYPE AS termtype, null AS excFinSector, null AS investArae, null AS investCountry, null AS finanSerModel, T1.OPERATE_MODE AS operateMode, null AS isShortTerm, null AS shortTerm, null AS isFreeRedem, null AS cashManaCate, null AS cmmode , null AS pmmode, null AS mname , null AS pricedMode, null AS ivstorientation, null AS contMode, null AS cooperationName, null AS saleArea, null AS raiseCcy, null AS cashPrinCcy, null AS cashProfCcy, null AS saleAmtStr, null AS raiseAmtPlan, T1.RAISE_PSTRDATE AS raisePstrdate, null AS raisePenddate, null AS investPrinDate, null AS investProfDate, null AS saleFeeRate, null AS investFeeRate, null AS inDepName, null AS inDepCode, null AS outDepCtry, null AS outDepName, null AS truFeeRate, null AS riskLevel, null AS riskType, null AS termRightFlag, null AS cusRedeemFlag, null AS creditFlag, null AS creditType, null AS creditMode, null AS invTypeRat, null AS yield, null AS remark, T1.UPDATE_TIME AS updateTime, T1.UPDATE_USER AS updateUser, T1.ERR_MSG AS errMsg, null AS fileNo, null AS fileNum, null AS tenFile, T1.ORG_DATA AS orgData FROM CHB_PRD_DECLARE_INFO_ERRODATA T1
1=1
AND T1.PROD_NAME LIKE concat(concat('%',#{prodName,jdbcType=VARCHAR}),'%')
AND T1.TERMTYPE = #{termtype}
ANd T1.OPERATE_MODE = #{operateMode}
AND T1.STATUS = #{status}
and T1.RAISE_PSTRDATE >= STR_TO_DATE(#{raisePstrdateStart},'%Y-%m-%d')
and T1.RAISE_PSTRDATE <= STR_TO_DATE(#{raisePstrdateEnd},'%Y-%m-%d')
ORDER BY statusValid DESC

mapper.update:
UPDATE CHB_PRD_DECLARE_INFO
SET  STATUS = 'D'
WHERE DECLARE_UUID = #{declareUuid,jdbcType=CHAR}
